Here's a complete implementation:

```csharp
// In Program.cs

// Configure request size limit (before builder.Build())
builder.Services.Configure<Microsoft.AspNetCore.Http.Features.FormOptions>(options =>
{
    options.MultipartBodyLengthLimit = 10 * 1024 * 1024; // 10MB
});

// If using Kestrel, also set the request body size limit
builder.WebHost.ConfigureKestrel(options =>
{
    options.Limits.MaxRequestBodySize = 10 * 1024 * 1024;
});

var app = builder.Build();

// Ensure uploads directory exists
var uploadsPath = Path.Combine(app.Environment.ContentRootPath, "uploads");
Directory.CreateDirectory(uploadsPath);

app.MapPost("/upload", async (IFormFile file) =>
{
    // Validate content type
    string[] allowedTypes = ["image/jpeg", "image/png"];
    if (!allowedTypes.Contains(file.ContentType))
    {
        return Results.BadRequest("Only JPEG and PNG files are allowed.");
    }

    // Validate size (defense in depth beyond the global limit)
    const long maxSize = 10 * 1024 * 1024;
    if (file.Length > maxSize)
    {
        return Results.BadRequest("File size must not exceed 10 MB.");
    }

    // Generate a safe unique filename preserving the extension
    var extension = Path.GetExtension(file.FileName).ToLowerInvariant();
    if (extension is not ".jpg" and not ".jpeg" and not ".png")
    {
        return Results.BadRequest("Invalid file extension.");
    }

    var fileName = $"{Guid.NewGuid()}{extension}";
    var filePath = Path.Combine(uploadsPath, fileName);

    await using var stream = new FileStream(filePath, FileMode.Create);
    await file.CopyToAsync(stream);

    return Results.Ok(new { fileName, size = file.Length });
})
.DisableAntiforgery()   // Required for non-browser API clients sending multipart/form-data
.DisableRequestSizeLimit() // Optional: remove if you want the global limit to apply instead
.WithName("UploadImage");
```

**Key points:**

- **Size limits** are set at both Kestrel and form-options level.
- **Content type + extension** are both validated to prevent spoofing.
- **`Guid` filenames** prevent path traversal and overwrites.
- **`.DisableAntiforgery()`** is needed since your pipeline has `UseAntiforgery()` — without it, API clients (Postman, mobile apps) will get 400s. Remove this if uploads only come from your Razor/Blazor forms that supply the antiforgery token.
- Replace `.DisableRequestSizeLimit()` with `.RequestSizeLimit(10 * 1024 * 1024)` if you want the endpoint to enforce its own explicit cap rather than removing limits entirely.
